#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    std::vector<std::vector<int>> sortMatrix(std::vector<std::vector<int>>& grid) {
        int n = grid.size();
        std::unordered_map<int, std::vector<int>> diagonals;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                diagonals[i - j].push_back(grid[i][j]);
            }
        }

        for (auto& pair : diagonals) {
            if (pair.first >= 0) {
                std::sort(pair.second.begin(), pair.second.end(), std::greater<int>());
            } else {
                std::sort(pair.second.begin(), pair.second.end());
            }
        }

        std::unordered_map<int, int> pos;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int key = i - j;
                grid[i][j] = diagonals[key][pos[key]++];
            }
        }
        return grid;
    }
};

import java.util.*;

class Solution {
    public int[][] sortMatrix(int[][] grid) {
        int n = grid.length;
        Map<Integer, List<Integer>> diagonals = new HashMap<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int key = i - j;
                diagonals.computeIfAbsent(key, k -> new ArrayList<>()).add(grid[i][j]);
            }
        }

        for (Map.Entry<Integer, List<Integer>> entry : diagonals.entrySet()) {
            if (entry.getKey() >= 0) {
                entry.getValue().sort(Collections.reverseOrder());
            } else {
                Collections.sort(entry.getValue());
            }
        }

        Map<Integer, Integer> pos = new HashMap<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int key = i - j;
                int idx = pos.getOrDefault(key, 0);
                grid[i][j] = diagonals.get(key).get(idx);
                pos.put(key, idx + 1);
            }
        }
        return grid;
    }
}

var sortMatrix = function(grid) {
    const n = grid.length;
    const diagonals = new Map();
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const key = i - j;
            if (!diagonals.has(key)) diagonals.set(key, []);
            diagonals.get(key).push(grid[i][j]);
        }
    }

    for (const [k, list] of diagonals.entries()) {
        if (k >= 0) {
            list.sort((a, b) => b - a);
        } else {
            list.sort((a, b) => a - b);
        }
    }

    const pos = new Map();
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const key = i - j;
            const idx = pos.get(key) || 0;
            grid[i][j] = diagonals.get(key)[idx];
            pos.set(key, idx + 1);
        }
    }
    return grid;
};
